// <auto-generated>
// Campground.Shared — compiled into each Campground plugin as internal code.
// Edit it in AHouseOfBards/Campground-Coordination/shared, never inside a plugin.
// </auto-generated>
#nullable enable

using System;
using System.IO;
using Campground.Shared.Registry;
using MediaBrowser.Common.Configuration;

namespace Campground.Shared.Storage
{
    /// <summary>
    /// Where Campground keeps shared state: <c>&lt;jellyfin data&gt;/campground</c>. Each plugin's own data goes
    /// in <c>&lt;jellyfin data&gt;/campground/&lt;pluginId&gt;</c>. The first plugin to start sets the root for all.
    /// </summary>
    internal static class CampgroundPaths
    {
        private const string StateSection = "paths";

        /// <summary>Call once at plugin start-up.</summary>
        internal static void Initialize(IApplicationPaths paths)
        {
            // Jellyfin's plugins folder too (1.0.1), so Ownership can tell whether FieldGuide is installed in a
            // caller that never hands it the plugin manager (issue #61).
            try
            {
                if (!string.IsNullOrEmpty(paths.PluginsPath))
                {
                    CampgroundRegistry.Section(StateSection).TryAdd("plugins", paths.PluginsPath);
                }
            }
            catch (Exception)
            {
                // A paths object that can't say where plugins live: Ownership falls back to counting reserved names.
            }

            Initialize(Path.Combine(paths.DataPath, "campground"));
        }

        /// <summary>Jellyfin's plugins folder, when <see cref="Initialize(IApplicationPaths)"/> was given one.</summary>
        internal static string? PluginsPath
            => CampgroundRegistry.Section(StateSection).TryGetValue("plugins", out var p) && p is string s ? s : null;

        /// <summary>Sets the root directly (tests, tools).</summary>
        internal static void Initialize(string root)
        {
            CampgroundRegistry.Section(StateSection).TryAdd("root", root);
            Directory.CreateDirectory(Root);
        }

        /// <summary>For tests only: replace the root.</summary>
        internal static void OverrideForTests(string root) => CampgroundRegistry.Section(StateSection)["root"] = root;

        /// <summary>The shared root.</summary>
        internal static string Root =>
            CampgroundRegistry.Section(StateSection).TryGetValue("root", out var r) && r is string s
                ? s
                : throw new InvalidOperationException("CampgroundPaths.Initialize has not been called.");

        /// <summary>True once a root is set.</summary>
        internal static bool IsInitialized => CampgroundRegistry.Section(StateSection).ContainsKey("root");

        // Windows won't make a folder called con, nul, com1 and so on, with or without an extension. Refused on every
        // OS so a data folder can be copied between them.
        private static bool IsReservedName(string id)
        {
            var dot = id.IndexOf('.');
            var stem = (dot < 0 ? id : id.Substring(0, dot)).TrimEnd().ToUpperInvariant();
            if (stem is "CON" or "PRN" or "AUX" or "NUL")
            {
                return true;
            }

            return stem.Length == 4 && (stem.StartsWith("COM", StringComparison.Ordinal) || stem.StartsWith("LPT", StringComparison.Ordinal))
                   && stem[3] >= '1' && stem[3] <= '9';
        }

        /// <summary>A plugin's own folder (created on demand).</summary>
        internal static string ForPlugin(string pluginId)
        {
            if (pluginId.IndexOfAny(Path.GetInvalidFileNameChars()) >= 0 || pluginId.Contains("..", StringComparison.Ordinal) || IsReservedName(pluginId))
            {
                throw new ArgumentException("Invalid plugin id.", nameof(pluginId));
            }

            var dir = Path.Combine(Root, pluginId);
            Directory.CreateDirectory(dir);
            return dir;
        }
    }
}
